import{_ as r,c as t,o as a,ag as o}from"./chunks/framework.CQuhCYrb.js";const g=JSON.parse('{"title":"Computer Network Operations (CNO)","description":"","frontmatter":{"title":"Computer Network Operations (CNO)"},"headers":[],"relativePath":"general/computer-network-operations-cno.md","filePath":"general/computer-network-operations-cno.md","lastUpdated":null}'),n={name:"general/computer-network-operations-cno.md"};function i(s,e,l,p,c,d){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="computer-network-operations-cno" tabindex="-1">Computer Network Operations (CNO) <a class="header-anchor" href="#computer-network-operations-cno" aria-label="Permalink to &quot;Computer Network Operations (CNO)&quot;">​</a></h1><h2 id="computer-network-operations-cno-1" tabindex="-1">Computer Network Operations (CNO) <a class="header-anchor" href="#computer-network-operations-cno-1" aria-label="Permalink to &quot;Computer Network Operations (CNO)&quot;">​</a></h2><p><strong>Computer Network Operations (CNO)</strong> encompasses offensive and defensive cyber operations as defined by the <strong>U.S. Department of Defense (DoD)</strong>. It includes three primary areas of focus:</p><ul><li><p><strong>Computer Network Attack (CNA)</strong>: Offensive operations to disrupt or disable adversary networks.</p></li><li><p><strong>Computer Network Defense (CND)</strong>: Measures to protect and secure critical systems.</p></li><li><p><strong>Computer Network Exploitation (CNE)</strong>: Intelligence-gathering activities within adversary networks.</p></li></ul><p>This page provides an overview of CNO, its pathways, prerequisites like the <strong>Computer Network Assessment Battery (CNAB)</strong>, and additional resources to aid in preparation and career advancement.</p><h3 id="pathway-to-cno-careers" tabindex="-1">Pathway to CNO Careers <a class="header-anchor" href="#pathway-to-cno-careers" aria-label="Permalink to &quot;Pathway to CNO Careers&quot;">​</a></h3><h3 id="step-1-passing-the-cnab" tabindex="-1">Step 1: Passing the CNAB <a class="header-anchor" href="#step-1-passing-the-cnab" aria-label="Permalink to &quot;Step 1: Passing the CNAB&quot;">​</a></h3><p>The <strong>Computer Network Assessment Battery (CNAB)</strong> is a prerequisite evaluation for many CNO-related roles. It assesses foundational technical skills and cognitive abilities, ensuring readiness for advanced training. Key components include:</p><ul><li><p><strong>Computer Networking Test</strong>: Focus on networking fundamentals like IP addressing and routing.</p></li><li><p><strong>Matrix Test</strong>: Evaluates pattern recognition and abstract reasoning.</p></li><li><p><strong>Work Background and Preferences Assessment</strong>: Gathers professional and technical experience relevant to CNO roles.</p></li></ul><h3 id="step-2-cyber-operations-training" tabindex="-1">Step 2: Cyber Operations Training <a class="header-anchor" href="#step-2-cyber-operations-training" aria-label="Permalink to &quot;Step 2: Cyber Operations Training&quot;">​</a></h3><p>After passing the CNAB, candidates undergo comprehensive training that covers:</p><ul><li><p><strong>Network Security and Defense</strong>: Principles of securing and monitoring networks.</p></li><li><p><strong>Offensive Operations</strong>: Techniques in penetration testing, vulnerability exploitation, and malware deployment.</p></li><li><p><strong>Advanced Tools</strong>: Hands-on experience with industry tools and frameworks.</p></li></ul><h3 id="step-3-certification" tabindex="-1">Step 3: Certification <a class="header-anchor" href="#step-3-certification" aria-label="Permalink to &quot;Step 3: Certification&quot;">​</a></h3><p>Candidates often pursue certifications that validate their technical skills and knowledge:</p><ul><li><p><strong>Certified Ethical Hacker (CEH)</strong></p></li><li><p><strong>Offensive Security Certified Professional (OSCP)</strong></p></li><li><p><strong>GIAC Penetration Tester (GPEN)</strong></p></li><li><p><strong>Certified Information Systems Security Professional (CISSP)</strong></p></li></ul><h3 id="step-4-assignment-to-specialized-units" tabindex="-1">Step 4: Assignment to Specialized Units <a class="header-anchor" href="#step-4-assignment-to-specialized-units" aria-label="Permalink to &quot;Step 4: Assignment to Specialized Units&quot;">​</a></h3><p>Graduates of CNO programs are typically assigned to specialized cyber units such as:</p><ul><li><p><strong>NSA Cyber Operations</strong></p></li><li><p><strong>U.S. Cyber Command</strong></p></li><li><p><strong>Military Branch Cyber Teams</strong> (e.g., Army Cyber, Air Force Cyber Warfare Operator, Navy CWE)</p></li></ul><h3 id="resources-for-cnab-and-cno-preparation" tabindex="-1">Resources for CNAB and CNO Preparation <a class="header-anchor" href="#resources-for-cnab-and-cno-preparation" aria-label="Permalink to &quot;Resources for CNAB and CNO Preparation&quot;">​</a></h3><h3 id="study-resources" tabindex="-1">Study Resources <a class="header-anchor" href="#study-resources" aria-label="Permalink to &quot;Study Resources&quot;">​</a></h3><ul><li><p><strong>Networking Fundamentals</strong>: O&#39;Reilly CCNA Books and Cisco Networking Academy resources.</p></li><li><p><strong>Pattern Recognition Practice</strong>: Online cognitive and abstract reasoning tests.</p></li><li><p><strong>Programming &amp; Scripting</strong>: Learn Python, Bash, and PowerShell with free resources like Codecademy and ShellSpells.</p></li><li><p><strong>Cybersecurity Basics</strong>: Explore courses from platforms like Coursera, edX, and Cybrary.</p></li></ul><h3 id="key-links" tabindex="-1">Key Links <a class="header-anchor" href="#key-links" aria-label="Permalink to &quot;Key Links&quot;">​</a></h3><ul><li><p><a href="https://www.nsa.gov/careers/" target="_blank" rel="noreferrer">NSA Career Pathways</a></p></li><li><p><a href="https://www.shellspells.net" target="_blank" rel="noreferrer">ShellSpells Cyber Training</a></p></li><li><p><a href="https://www.remnote.com/a/CNAB-Prep-Article/61081fba82b32a0045bac1b3" target="_blank" rel="noreferrer">RemNote CNAB Prep Guide</a></p></li></ul><h3 id="additional-resources" tabindex="-1">Additional Resources <a class="header-anchor" href="#additional-resources" aria-label="Permalink to &quot;Additional Resources&quot;">​</a></h3><ul><li><p><strong>CNODP (Computer Network Operations Development Program)</strong>: An NSA-led initiative to develop expertise in network protection, hardware exploitation, and advanced problem-solving.</p></li><li><p><strong>Critical DoD Publications</strong>: Study U.S. policies and guidelines on CNO.</p></li></ul><h3 id="contribute-to-this-page" tabindex="-1">Contribute to This Page <a class="header-anchor" href="#contribute-to-this-page" aria-label="Permalink to &quot;Contribute to This Page&quot;">​</a></h3><p>This page is a living resource for individuals pursuing careers in CNO. If you have additional insights, resources, or corrections, please edit and contribute to help others in their journey.</p>',27)])])}const h=r(n,[["render",i]]);export{g as __pageData,h as default};
